CREATE TABLE IF NOT EXISTS usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(80) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,rol ENUM('administrador','cajero','cocinero') NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categorias(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS productos(id INT AUTO_INCREMENT PRIMARY KEY,categoria_id INT NOT NULL,nombre VARCHAR(100) NOT NULL,precio DECIMAL(10,2) NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(categoria_id) REFERENCES categorias(id));
CREATE TABLE IF NOT EXISTS insumos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,unidad VARCHAR(15) NOT NULL,stock DECIMAL(12,3) NOT NULL DEFAULT 0,stock_minimo DECIMAL(12,3) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS recetas(producto_id INT NOT NULL,insumo_id INT NOT NULL,cantidad DECIMAL(12,3) NOT NULL,PRIMARY KEY(producto_id,insumo_id),FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE CASCADE,FOREIGN KEY(insumo_id) REFERENCES insumos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS cajas(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,base_inicial DECIMAL(12,2) NOT NULL,abierta_en DATETIME DEFAULT CURRENT_TIMESTAMP,cerrada_en DATETIME NULL,total_ventas DECIMAL(12,2) NULL,esperado DECIMAL(12,2) NULL,contado DECIMAL(12,2) NULL,diferencia DECIMAL(12,2) NULL,estado ENUM('abierta','cerrada') NOT NULL DEFAULT 'abierta',FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS pedidos(id INT AUTO_INCREMENT PRIMARY KEY,mesa VARCHAR(20) NOT NULL,tipo ENUM('mesa','llevar') NOT NULL DEFAULT 'mesa',estado ENUM('pendiente','en_preparacion','listo','entregado','cancelado') NOT NULL DEFAULT 'pendiente',subtotal DECIMAL(12,2) NOT NULL,impuesto DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,pagado TINYINT(1) NOT NULL DEFAULT 0,usuario_id INT NOT NULL,caja_id INT NOT NULL,creado_en DATETIME DEFAULT CURRENT_TIMESTAMP,inicio_prep_en DATETIME NULL,listo_en DATETIME NULL,motivo_cancelacion VARCHAR(200) NULL,INDEX(estado),INDEX(creado_en));
CREATE TABLE IF NOT EXISTS pedido_items(id INT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,producto_id INT NOT NULL,nombre VARCHAR(100) NOT NULL,precio DECIMAL(10,2) NOT NULL,cantidad INT NOT NULL,observaciones VARCHAR(200) NULL,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pagos(id INT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,caja_id INT NOT NULL,metodo ENUM('efectivo','tarjeta','transferencia') NOT NULL,monto DECIMAL(12,2) NOT NULL,recibido DECIMAL(12,2) NOT NULL,creado_en DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pedido_id) REFERENCES pedidos(id));
CREATE TABLE IF NOT EXISTS movimientos_inventario(id INT AUTO_INCREMENT PRIMARY KEY,insumo_id INT NOT NULL,pedido_id INT NULL,cantidad DECIMAL(12,3) NOT NULL,tipo VARCHAR(20) NOT NULL DEFAULT 'consumo',creado_en DATETIME DEFAULT CURRENT_TIMESTAMP)
